contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (value)); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= value);
        uint balBefore = address(c).balance;
        bool reverted;
        c.Put{value: value}(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;
        assert((!reverted && balAfter == balBefore + value) || (reverted && balAfter == balBefore));
    }

    receive() external payable {}
}

